const fs = require('fs');
const d = require('docx');
const {
  Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType, PageBreak,
  Table, TableRow, TableCell, WidthType, ShadingType, BorderStyle, LevelFormat,
  Header, Footer, PageNumber, TableOfContents, convertInchesToTwip
} = d;

const NAVY = "2E2A5B";
const GOLD = "A98A5C";
const GREY = "595959";
const BAND = "EDEBF4";

const FONT = "Calibri";
const CW = [3060, 1500, 1500, 3300]; // benchmark table widths sum 9360
const PAGE_W = 9360;

function P(text, opts = {}) {
  return new Paragraph({
    spacing: { after: opts.after ?? 120, line: 276 },
    alignment: opts.align,
    indent: opts.indent,
    children: [new TextRun({ text, font: FONT, size: opts.size ?? 21, bold: opts.bold, italics: opts.italics, color: opts.color })]
  });
}

function H1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    spacing: { before: 360, after: 180 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 8, color: GOLD, space: 6 } },
    children: [new TextRun({ text, font: FONT, size: 30, bold: true, color: NAVY })]
  });
}

function H2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    spacing: { before: 260, after: 120 },
    children: [new TextRun({ text, font: FONT, size: 24, bold: true, color: NAVY })]
  });
}

function H3(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_3,
    spacing: { before: 200, after: 80 },
    children: [new TextRun({ text, font: FONT, size: 21, bold: true, color: GOLD })]
  });
}

function bullet(text, level = 0) {
  return new Paragraph({
    numbering: { reference: "bullets", level },
    spacing: { after: 60, line: 264 },
    children: [new TextRun({ text, font: FONT, size: 21 })]
  });
}

function check(text) {
  return new Paragraph({
    spacing: { after: 60, line: 264 },
    indent: { left: 260, hanging: 260 },
    children: [
      new TextRun({ text: "\u2610   ", font: FONT, size: 22, color: GOLD }),
      new TextRun({ text, font: FONT, size: 21 })
    ]
  });
}

function numbered(text) {
  return new Paragraph({
    numbering: { reference: "steps", level: 0 },
    spacing: { after: 80, line: 264 },
    children: [new TextRun({ text, font: FONT, size: 21 })]
  });
}

function cell(text, opts = {}) {
  return new TableCell({
    width: { size: opts.w, type: WidthType.DXA },
    shading: opts.shade ? { type: ShadingType.CLEAR, fill: opts.shade, color: "auto" } : undefined,
    margins: { top: 80, bottom: 80, left: 110, right: 110 },
    verticalAlign: "center",
    children: (Array.isArray(text) ? text : [text]).map(t =>
      new Paragraph({
        spacing: { after: 0, line: 252 },
        alignment: opts.align,
        children: [new TextRun({ text: t, font: FONT, size: opts.size ?? 19, bold: opts.bold, color: opts.color })]
      })
    )
  });
}

function table(headers, rows, widths) {
  const total = widths.reduce((a, b) => a + b, 0);
  return new Table({
    columnWidths: widths,
    width: { size: total, type: WidthType.DXA },
    borders: {
      top: { style: BorderStyle.SINGLE, size: 2, color: "BFBFBF" },
      bottom: { style: BorderStyle.SINGLE, size: 2, color: "BFBFBF" },
      left: { style: BorderStyle.SINGLE, size: 2, color: "BFBFBF" },
      right: { style: BorderStyle.SINGLE, size: 2, color: "BFBFBF" },
      insideHorizontal: { style: BorderStyle.SINGLE, size: 2, color: "D9D9D9" },
      insideVertical: { style: BorderStyle.SINGLE, size: 2, color: "D9D9D9" }
    },
    rows: [
      new TableRow({
        tableHeader: true,
        children: headers.map((h, i) => cell(h, { w: widths[i], shade: NAVY, bold: true, color: "FFFFFF", size: 19 }))
      }),
      ...rows.map((r, ri) => new TableRow({
        children: r.map((c, i) => cell(c, {
          w: widths[i],
          shade: ri % 2 === 1 ? BAND : undefined,
          bold: i === 0
        }))
      }))
    ]
  });
}

const body = [];

// ---------------------------------------------------------------- Cover
body.push(new Paragraph({ spacing: { before: 2200, after: 0 }, children: [
  new TextRun({ text: "THE LUXORA COLLECTIVE", font: FONT, size: 22, bold: true, color: GOLD, characterSpacing: 60 })
]}));
body.push(new Paragraph({ spacing: { before: 200, after: 0 }, children: [
  new TextRun({ text: "The Weekly Operating Standard", font: FONT, size: 56, bold: true, color: NAVY })
]}));
body.push(new Paragraph({
  spacing: { before: 120, after: 400 },
  border: { bottom: { style: BorderStyle.SINGLE, size: 12, color: GOLD, space: 10 } },
  children: [new TextRun({ text: "Weekly Benchmarks, Team Scorecard, Sales Goals, and Front Desk Standards", font: FONT, size: 26, color: GREY })]
}));
body.push(P("A working document, not a report.", { size: 24, italics: true, color: GREY, after: 600 }));
body.push(P("Prepared for:  ____________________________________", { size: 22, after: 160 }));
body.push(P("Prepared by:  The Luxora Collective", { size: 22, after: 160 }));
body.push(P("Date:  ____________________________________", { size: 22, after: 1000 }));
body.push(P("theluxoracollective.co", { size: 20, color: GOLD, bold: true }));
body.push(new Paragraph({ children: [new PageBreak()] }));

// ---------------------------------------------------------------- Read this first
body.push(H1("Read This First"));

body.push(P("Most practices at your revenue level do not have a measurement problem. They have a rhythm problem. The numbers exist somewhere, usually inside a practice management system that nobody opens on a Monday, and by the time anyone looks at them the quarter is already decided."));
body.push(P("This document fixes the rhythm. It contains four things that work together, and they are worth very little separately:"));

body.push(bullet("The Weekly Benchmark Standard. What good looks like, with a source behind every number, so your targets are defensible rather than arbitrary."));
body.push(bullet("The Weekly Scorecard. Seventeen numbers entered every Friday. Every rate calculates itself. It is delivered as a companion workbook."));
body.push(bullet("The Sales Goal Method. How to turn one annual number into a daily activity target that a person can actually act on."));
body.push(bullet("The Front Desk Standards. The specific behaviors that produce the numbers on the scorecard."));

body.push(H2("The single idea behind all of it"));
body.push(P("A scorecard does not improve a practice. A conversation improves a practice. The scorecard exists to make that conversation short, specific, and impossible to avoid."));
body.push(P("Which means the goal of this system is not a complete dashboard. It is a thirty minute meeting on Monday morning where the team looks at one number, agrees on why it moved, and leaves with one action. Everything in this document is built to serve that meeting."));

body.push(H2("What to expect, honestly"));
body.push(table(
  ["Time frame", "What actually happens"],
  [
    ["Weeks 1 to 2", "The numbers will be wrong and the team will be uncomfortable. This is normal and it is not a failure. You are discovering how your practice actually counts things."],
    ["Weeks 3 to 4", "The numbers stabilize. The first honest gap becomes visible, and it is almost never the one the owner expected."],
    ["Weeks 5 to 8", "The first metric moves. This is the moment the team stops treating the scorecard as paperwork, because they watched their own effort show up in a number."],
    ["Weeks 9 to 13", "A second and third metric move without being pushed. The rhythm is now the culture rather than an initiative."]
  ],
  [1800, 7560]
));
body.push(P("Practices that abandon this system almost always do so in week two, for the same reason people quit a gym in week two. Nothing has changed yet. Get to week five.", { italics: true, after: 200 }));

body.push(new Paragraph({ children: [new PageBreak()] }));

// ---------------------------------------------------------------- Part 1
body.push(H1("Part One: The Weekly Benchmark Standard"));
body.push(P("These are the numbers that separate the top quartile of med spas from the rest. Every figure below is sourced. Show your team the source. A target that arrives with evidence stops being the owner's opinion and starts being a standard."));

body.push(H2("The benchmark table"));
body.push(table(
  ["Metric", "Industry average", "Top performer", "What it actually tells you"],
  [
    ["Consult-to-treatment conversion", "55% to 75%", "80% and above", "Sales skill at the point of care. This is the most expensive leak in most practices because the client is already in the room and already paid for."],
    ["Patient retention rate", "52%", "70%", "Whether first-time patients return. The bottom quartile retains 35%. Same industry, double the outcome."],
    ["90-day return rate", "Varies widely", "60% and above", "The earliest reliable signal of a retention problem, months before revenue reflects it."],
    ["Average revenue per visit", "$450 to $600", "$600 and above", "Pricing and service mix. Below $300 requires attention the same week."],
    ["Revenue per provider hour", "$450 and above", "$600 to $800", "The truest efficiency measure in the building. A skilled injector performing basic facials destroys this number. Below $250 signals a serious problem."],
    ["Provider gap rate", "20% to 35%", "Below 10%", "Unbookable time you pay for and never sell. The quietest cost in the practice."],
    ["Rebooking and cancellation", "37% cancel", "4% cancel", "Guests rebooked once cancel at 37%. Rebooked twice or more, cancellation falls to 4%. Rebooking is retention."],
    ["Retail as a percent of revenue", "Under 10%", "10% to 15%", "The highest margin dollars available to you, sitting on a shelf, requiring no additional labor."],
    ["Discounts as a percent of revenue", "Varies", "Below 5%", "A silent margin leak. Practices that do not track this discover it at year end."],
    ["Marketing spend", "8% to 12% of revenue", "8% to 10%", "Outside this band signals either underinvestment or an efficiency problem further down the funnel."],
    ["Cost per booked consultation", "$65 to $180", "Under $100", "The price of a stranger. Judge it against your average consult purchase value before calling it expensive."],
    ["Lead response time", "Over 30 minutes", "Under 5 minutes", "Responding within five minutes makes conversion 21 times more likely than responding after thirty. This is the cheapest improvement available to any practice."],
    ["Google reviews", "Under 20", "100 and above", "Practices with 100 or more reviews receive 3.2 times more clicks from local search. It compounds and it costs nothing but the ask."]
  ],
  CW
));

body.push(H2("Sources"));
body.push(P("Zenoti 2026 Beauty and Wellness Benchmark Report, medspa edition. AmSpa Benchmark Report. Qsight 2025 retention data. Pabau Med Spa KPI Guide. Prospyr 2026 revenue metrics. BrightLocal local search data. Lead Response Management Study.", { size: 18, color: GREY }));

body.push(H2("How to use benchmarks without demoralizing your team"));
body.push(P("Benchmarks are a tool, and like any tool they can be used to build or to injure. Four rules:"));
body.push(numbered("Never open a meeting with the top performer column. Open with where you were last quarter. Progress motivates people. Distance from perfection does not."));
body.push(numbered("Use the industry average column to answer the question every team asks silently, which is whether the target is fair. A number with a source behind it ends that argument in ten seconds."));
body.push(numbered("Say out loud that the gap between the bottom and top quartile is roughly double on almost every line, and that the difference is systems rather than talent. Systems are learnable. Talent feels like a verdict."));
body.push(numbered("Pick your two worst gaps against the industry average, not against the top performer. Close those first. The first twenty percent of improvement costs the least and teaches the team that the scorecard works."));

body.push(new Paragraph({ children: [new PageBreak()] }));

// ---------------------------------------------------------------- Part 2
body.push(H1("Part Two: The Weekly Scorecard"));
body.push(P("The scorecard is delivered as a companion Excel workbook. This section explains how to run it. Read this once with your manager, then work from the workbook."));

body.push(H2("The weekly rhythm"));
body.push(table(
  ["When", "Who", "What happens", "How long"],
  [
    ["Friday at close", "Front desk lead", "Enter the week's seventeen input numbers into the Weekly Scorecard tab. Every rate calculates itself.", "15 minutes"],
    ["Friday evening", "Owner or manager", "Look at the Status column. Decide which single number you will raise on Monday. Do not send it to the team.", "5 minutes"],
    ["Monday at 9:00 AM", "Whole team", "The huddle. Scorecard on a screen, not on paper, not in an email.", "30 minutes"],
    ["Friday following", "The named owner", "The action assigned Monday is due. No extensions, because the next Monday is coming regardless.", "Varies"]
  ],
  [1500, 1700, 4860, 1300]
));

body.push(H2("The thirty minute Monday huddle"));
body.push(P("This agenda is the entire system. Everything else is preparation for it."));
body.push(numbered("Minutes 0 to 5. Read the Status column left to right out loud. Name every green. Do not explain them, do not analyze them, just name them. The team needs to hear what is working before they hear what is not."));
body.push(numbered("Minutes 5 to 10. Name the single worst red. Only one. If three are red, you still name one. A team that is asked to fix three things fixes zero."));
body.push(numbered("Minutes 10 to 25. Ask why, not who. The question is what in our process produced this number, not whose fault it is. The moment a scorecard becomes a weapon, the inputs start getting inflated and you lose the instrument permanently."));
body.push(numbered("Minutes 25 to 30. Assign one owner and one action, due Friday. A verb and a deadline. Write it in the Notes row of the workbook so it exists somewhere other than everyone's memory."));
body.push(numbered("The following Monday, the first item on the agenda is whether that number moved. Not whether the action was completed. Whether the number moved. This distinction is what separates practices that improve from practices that hold meetings."));

body.push(H2("What every input means, precisely"));
body.push(P("Ambiguity in the definitions produces numbers that cannot be compared week to week, which is the same as having no numbers. Agree on these once, write them down, and do not renegotiate them mid-quarter."));

body.push(table(
  ["Input", "The precise definition", "The trap"],
  [
    ["Total collected revenue", "Money actually collected this week, not billed, not promised, not sitting in a payment plan.", "Counting a signed package before the card runs."],
    ["Total client visits", "Individual client arrivals. One client receiving three services in one appointment is one visit.", "Counting services instead of visits, which inflates volume and deflates revenue per visit."],
    ["New client inquiries", "Every first contact from someone not currently a client: calls, forms, DMs, walk-ins.", "Only counting phone calls. In 2026, most first contact is not a phone call."],
    ["New client inquiries booked", "Inquiries that ended with an appointment on the calendar.", "Counting a callback promise as a booking."],
    ["Consults conducted", "Consultations that were booked and actually seated.", "Counting no-shows, which quietly flatters your conversion rate."],
    ["Consults converted", "Consults where the client purchased treatment within 48 hours.", "Counting a soft yes. If no money moved, it did not convert."],
    ["Clients checked out", "Clients who completed a visit and left. Denominator for rebooking.", "Should track close to visits. If it does not, someone is leaving without a checkout, which is its own problem."],
    ["Clients rebooked at checkout", "Left the building with a next appointment on the calendar.", "A text three days later is a recovery, not a rebook. Recoveries are good. They are not this number."],
    ["Provider hours available", "Hours you are paying for and could have sold.", "Excluding admin blocks that were never going to be sold anyway, which hides real capacity."],
    ["Provider hours booked", "Hours actually filled with a paying client.", "Counting a booked no-show as filled."],
    ["Retail revenue", "Product sales only. No service revenue.", "Bundling retail into a package price and then wondering why retail looks flat."],
    ["Discounts and comps", "The dollar value of every discount, comp, courtesy, and friend-of-the-practice adjustment.", "Not tracking comps at all. They are discounts with better manners."],
    ["New memberships sold", "New recurring agreements signed and processed.", "Counting a verbal commitment."],
    ["Memberships cancelled", "Members who cancelled or failed payment and were not recovered.", "Not tracking this, which makes a leaking program look like a growing one."],
    ["New Google reviews", "Reviews published this week.", "Counting requests sent rather than reviews received."],
    ["No-shows and late cancellations", "Appointments lost inside your cancellation window.", "Treating a same-day cancellation as a cancellation rather than a lost hour."],
    ["Total appointments scheduled", "Every appointment on the books for the week. Denominator for the no-show rate.", "Using visits instead, which mathematically hides the problem."]
  ],
  [1800, 4380, 3180]
));

body.push(H2("Reading the scorecard like an operator"));
body.push(P("A number in isolation is trivia. Numbers in relationship are a diagnosis. Four patterns to look for:"));
body.push(H3("Revenue is flat but visits are up"));
body.push(P("Your mix is drifting toward low-value services, or discounting has become a habit. Check average revenue per visit and discounts as a percent of revenue in the same breath. You are working harder for the same money, which is the most demoralizing way to run a practice."));
body.push(H3("Inquiries are up but revenue is flat"));
body.push(P("You are paying for demand you are not converting. Look at inquiry-to-booking rate before you look at anything else. This is almost always the cheapest fix in the building, and it is almost always where practices spend the least attention."));
body.push(H3("Consult conversion is strong but retention is weak"));
body.push(P("You sell well and follow through poorly. Check rebook-at-checkout. You are buying the same client repeatedly, which is the single most expensive way to run a med spa."));
body.push(H3("Utilization is high but revenue per provider hour is low"));
body.push(P("Your calendar is full of the wrong work. A skilled injector performing basic facials is the classic version of this. Everyone is busy, everyone is tired, and the number does not move."));

body.push(new Paragraph({ children: [new PageBreak()] }));

// ---------------------------------------------------------------- Part 3
body.push(H1("Part Three: Sales Goals That a Team Can Actually Act On"));

body.push(P("The most common mistake in goal setting is presenting an annual number to a team. Nobody has ever walked onto a floor and executed against two point four million dollars. People execute against Tuesday."));
body.push(P("The Sales Goal Calculator tab in the companion workbook does this math for you. This section explains the logic so you can defend it in the room."));

body.push(H2("The cascade"));
body.push(P("The method is a single chain of division, and its power is that it converts an intimidating goal into something a person can hold."));

body.push(table(
  ["Step", "The question it answers", "The number the team hears"],
  [
    ["1. The goal", "What does the year require every week?", "Annual goal divided by operating weeks. This is the only revenue number you ever put on a wall."],
    ["2. Visits", "How many clients does that require?", "Weekly revenue divided by average revenue per visit. If this exceeds capacity, the answer is price or mix, not more hours."],
    ["3. Capacity", "Do we have the hours to deliver it?", "Weekly revenue divided by target revenue per provider hour. Compare against hours available."],
    ["4. Selling", "How many consults must close?", "Consult revenue divided by average purchase value, then divided by conversion rate to get consults required."],
    ["5. Front desk", "How many inquiries must we answer?", "Consults required, adjusted for show rate, divided by inquiry-to-booking rate. This is the marketing requirement."],
    ["6. Recurring", "What protects us from a slow month?", "Membership revenue goal divided by average price, plus churn replacement. The number that changes your valuation."],
    ["7. Margin", "What are we leaving on the table?", "Retail target and marketing budget as percentages of the weekly number."]
  ],
  [1300, 3200, 4860]
));

body.push(H2("The rule of one number per role"));
body.push(P("Every person on the floor should be able to answer one question without looking anything up: what is my number today? Not the practice's number. Theirs."));

body.push(table(
  ["Role", "Their one number", "Why this one"],
  [
    ["Owner", "Weekly revenue versus target", "The only number that aggregates everything else. Everyone else's number rolls into it."],
    ["Front desk", "Inquiries booked today", "The only metric they fully control. It is also the cheapest revenue in the building."],
    ["Provider or injector", "Revenue per booked hour", "Captures mix, pricing, and rebooking in one figure. It rewards judgment rather than volume."],
    ["Consultant or coordinator", "Consult conversion rate", "The clearest measure of the highest-leverage conversation in the practice."],
    ["Manager", "Net new memberships", "Recurring revenue is the only metric that compounds while everyone sleeps."]
  ],
  [1600, 2500, 5260]
));
body.push(P("Five people, five numbers. Not one dashboard with forty metrics that everybody nods at and nobody owns.", { italics: true }));

body.push(H2("How to present goals on Monday without losing the room"));
body.push(numbered("Present the weekly number, never the annual one. Two point four million is a threat. Forty-eight thousand is a plan."));
body.push(numbered("Present the daily activity number alongside it. Seven inquiries a day is something a person can picture. Ninety-six visits a week is arithmetic."));
body.push(numbered("Show the math on a whiteboard once, in full. A team that watched the number get built will argue with the assumptions, which is exactly what you want. A team handed a number without the math will comply quietly and miss it."));
body.push(numbered("Name the lever you are pulling this quarter, and only one. Conversion, or retention, or mix. A practice that pulls three levers at once cannot tell you which one worked, which means it has learned nothing and will have to guess again next quarter."));
body.push(numbered("When the goal genuinely does not pencil, say so in the room. The honest answer is almost always price, mix, or retention. More leads is rarely the answer, and it is always the most expensive one."));

body.push(new Paragraph({ children: [new PageBreak()] }));

// ---------------------------------------------------------------- Part 4
body.push(H1("Part Four: The Front Desk Standard"));

body.push(P("The front desk is the highest-leverage and lowest-invested-in position in almost every med spa. It touches every dollar before a provider does, and it is usually the least trained role in the building. This section is the working checklist."));
body.push(P("Print the daily checklists. Laminate them. A checklist that lives in a shared drive is a document. A checklist on the desk is a standard.", { italics: true }));

body.push(H2("Opening: the first twenty minutes"));
body.push(check("Unlock, lights, music at conversation volume, temperature checked. The room should feel handled before anyone arrives."));
body.push(check("Walk the client path from the front door to the treatment room. Look at it as a first-time client would. Fix what you see now, not later."));
body.push(check("Review today's schedule out loud with the provider team. Name every consult, every first-time client, and every gap."));
body.push(check("Flag every first-time client by name. Somebody should greet them by name within three seconds of arrival."));
body.push(check("Identify every gap in the calendar and name who is responsible for filling it today."));
body.push(check("Clear overnight inquiries: voicemail, web forms, DMs, texts, missed calls. Every one gets a response before the first appointment."));
body.push(check("Confirm tomorrow's appointments if the automated cadence has not already. Verify that it ran."));
body.push(check("Check retail shelves: stocked, faced, priced, dusted. Empty shelves do not sell."));

body.push(H2("The phone and inquiry standard"));
body.push(P("This is where the most recoverable revenue in the practice is lost, quietly, every day."));
body.push(check("Every inquiry receives a response within five minutes during business hours. Responding within five minutes makes conversion 21 times more likely than responding after thirty. There is no cheaper improvement available to you."));
body.push(check("The phone is answered within three rings, by a person, with the practice name and the answerer's name."));
body.push(check("Never let a call end without an offer of a specific time. Not a callback. Not information. A time."));
body.push(check("Offer two specific options rather than asking when they are free. Open-ended questions produce open-ended outcomes."));
body.push(check("Capture the name, the number, and the source of every inquiry before anything else. An uncaptured inquiry is unrecoverable."));
body.push(check("If they will not book, get permission to follow up and put the follow-up on the calendar before you hang up."));
body.push(check("Log every inquiry the same day, without exception. The scorecard is only as honest as this step."));
body.push(check("Voicemail and after-hours inquiries are cleared first thing, before the first appointment, every morning."));

body.push(H2("Check-in"));
body.push(check("Greet by name within three seconds. Stand up. This costs nothing and it is noticed every single time."));
body.push(check("First-time clients are walked in, not pointed. Offer water. Introduce them to their provider by name."));
body.push(check("Confirm contact details and consent forms are current before the client sits down, not after."));
body.push(check("Hand off to the provider with a spoken sentence about who this client is and what they came for. A silent handoff makes the client repeat themselves, which reads as a practice that does not talk to itself."));

body.push(H2("Checkout: where retention is actually decided"));
body.push(P("Rebooking is not a nicety. Guests rebooked once cancel at 37 percent. Guests rebooked twice or more cancel at 4 percent. The checkout desk is a retention instrument."));
body.push(check("Rebook before payment, never after. Once the card is out, the client is already leaving."));
body.push(check("Ask a closed question with a clinical reason: the provider recommends four weeks, would Tuesday or Thursday work better? Never ask whether they would like to rebook."));
body.push(check("If they decline, ask once more with a reason attached, then book a reminder task rather than pressing a third time."));
body.push(check("Make one product recommendation tied to what the provider actually said in the room. Not a script. A reference."));
body.push(check("Mention the membership when the math favors the client, and only then. If this visit plus their next would cost more than membership, say so plainly. Clients do not resent being shown arithmetic."));
body.push(check("Ask for the review at the moment of visible satisfaction, not by email three days later. Send the link while they are standing there."));
body.push(check("Log the rebook, the retail sale, and the membership conversation in the system before the next client reaches the desk."));

body.push(H2("Closing"));
body.push(check("Every inquiry from today has a response and a logged outcome. No exceptions carried overnight."));
body.push(check("Tomorrow's schedule is confirmed and every gap is named."));
body.push(check("Tomorrow's first-time clients and consults are flagged for the provider team."));
body.push(check("Retail restocked and faced for the morning."));
body.push(check("Today's numbers noted for the Friday scorecard entry. Five minutes now saves an hour of reconstruction on Friday."));
body.push(check("Reception surfaces cleared. The last thing you see tonight is the first thing a client sees tomorrow."));

body.push(H2("Friday: the scorecard entry"));
body.push(check("Enter the seventeen input numbers in the Weekly Scorecard tab. Fifteen minutes, at close, without exception."));
body.push(check("Do not round, do not estimate, do not flatter. A soft consult still counts as a consult."));
body.push(check("Note anything unusual that would explain a number: a provider out sick, a holiday, a device down. Context prevents a panic on Monday."));
body.push(check("Confirm last week's assigned action was completed and be ready to say whether the number moved."));

body.push(new Paragraph({ children: [new PageBreak()] }));

// ---------------------------------------------------------------- Part 5
body.push(H1("Part Five: The First Thirty Days"));
body.push(P("Do not roll all of this out at once. A team handed four new systems in one week adopts none of them."));

