const fs = require('fs');
const d = require('docx');
const {
  Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType, PageBreak,
  Table, TableRow, TableCell, WidthType, ShadingType, BorderStyle, LevelFormat,
  Header, Footer, PageNumber
} = d;

const NAVY = "2E2A5B", GOLD = "A98A5C", GREY = "595959", BAND = "EDEBF4", RED = "9C2B2B";
const FONT = "Calibri";

function P(t, o = {}) {
  return new Paragraph({
    spacing: { after: o.after ?? 120, line: 276 },
    alignment: o.align,
    shading: o.shade ? { type: ShadingType.CLEAR, fill: o.shade, color: "auto" } : undefined,
    border: o.box ? {
      top: { style: BorderStyle.SINGLE, size: 6, color: o.box, space: 8 },
      bottom: { style: BorderStyle.SINGLE, size: 6, color: o.box, space: 8 },
      left: { style: BorderStyle.SINGLE, size: 18, color: o.box, space: 10 },
      right: { style: BorderStyle.SINGLE, size: 6, color: o.box, space: 8 }
    } : undefined,
    children: [new TextRun({ text: t, font: FONT, size: o.size ?? 21, bold: o.bold, italics: o.italics, color: o.color })]
  });
}
const H1 = t => new Paragraph({
  heading: HeadingLevel.HEADING_1, spacing: { before: 340, after: 170 },
  border: { bottom: { style: BorderStyle.SINGLE, size: 8, color: GOLD, space: 6 } },
  children: [new TextRun({ text: t, font: FONT, size: 30, bold: true, color: NAVY })]
});
const H2 = t => new Paragraph({
  heading: HeadingLevel.HEADING_2, spacing: { before: 240, after: 110 },
  children: [new TextRun({ text: t, font: FONT, size: 24, bold: true, color: NAVY })]
});
const H3 = t => new Paragraph({
  heading: HeadingLevel.HEADING_3, spacing: { before: 190, after: 70 },
  children: [new TextRun({ text: t, font: FONT, size: 21, bold: true, color: GOLD })]
});
const bul = (t, l = 0) => new Paragraph({
  numbering: { reference: "b", level: l }, spacing: { after: 60, line: 264 },
  children: [new TextRun({ text: t, font: FONT, size: 21 })]
});
const num = t => new Paragraph({
  numbering: { reference: "n", level: 0 }, spacing: { after: 80, line: 264 },
  children: [new TextRun({ text: t, font: FONT, size: 21 })]
});
function cell(t, o = {}) {
  return new TableCell({
    width: { size: o.w, type: WidthType.DXA },
    shading: o.shade ? { type: ShadingType.CLEAR, fill: o.shade, color: "auto" } : undefined,
    margins: { top: 90, bottom: 90, left: 110, right: 110 },
    verticalAlign: "center",
    children: (Array.isArray(t) ? t : [t]).map(x => new Paragraph({
      spacing: { after: 0, line: 252 }, alignment: o.align,
      children: [new TextRun({ text: x, font: FONT, size: o.size ?? 19, bold: o.bold, color: o.color })]
    }))
  });
}
function table(heads, rows, w, opts = {}) {
  return new Table({
    columnWidths: w, width: { size: w.reduce((a, b) => a + b, 0), type: WidthType.DXA },
    borders: {
      top: { style: BorderStyle.SINGLE, size: 2, color: "BFBFBF" },
      bottom: { style: BorderStyle.SINGLE, size: 2, color: "BFBFBF" },
      left: { style: BorderStyle.SINGLE, size: 2, color: "BFBFBF" },
      right: { style: BorderStyle.SINGLE, size: 2, color: "BFBFBF" },
      insideHorizontal: { style: BorderStyle.SINGLE, size: 2, color: "D9D9D9" },
      insideVertical: { style: BorderStyle.SINGLE, size: 2, color: "D9D9D9" }
    },
    rows: [
      new TableRow({
        tableHeader: true,
        children: heads.map((h, i) => cell(h, { w: w[i], shade: NAVY, bold: true, color: "FFFFFF", align: opts.center ? AlignmentType.CENTER : undefined }))
      }),
      ...rows.map((r, ri) => new TableRow({
        children: r.map((c, i) => cell(c, {
          w: w[i], shade: ri % 2 ? BAND : undefined, bold: i === 0,
          align: opts.center && i > 0 ? AlignmentType.CENTER : undefined
        }))
      }))
    ]
  });
}
const numbering = {
  config: [
    { reference: "b", levels: [
      { level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 400, hanging: 220 } } } },
      { level: 1, format: LevelFormat.BULLET, text: "\u25E6", alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 760, hanging: 220 } } } }
    ]},
    { reference: "n", levels: [
      { level: 0, format: LevelFormat.DECIMAL, text: "%1.", alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 400, hanging: 260 } } } }
    ]}
  ]
};
function makeDoc(children, headerText) {
  return new Document({
    creator: "The Luxora Collective", numbering,
    styles: { default: { document: { run: { font: FONT, size: 21 } } } },
    sections: [{
      properties: { page: { size: { width: 12240, height: 15840 }, margin: { top: 1080, bottom: 1080, left: 1440, right: 1440 } } },
      headers: { default: new Header({ children: [new Paragraph({
        alignment: AlignmentType.RIGHT, spacing: { after: 100 },
        border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: "D9D9D9", space: 4 } },
        children: [new TextRun({ text: headerText, font: FONT, size: 16, color: GREY })]
      })]})},
      footers: { default: new Footer({ children: [new Paragraph({
        alignment: AlignmentType.CENTER,
        children: [
          new TextRun({ text: "theluxoracollective.co          ", font: FONT, size: 16, color: GOLD }),
          new TextRun({ children: [PageNumber.CURRENT], font: FONT, size: 16, color: GREY })
        ]
      })]})},
      children
    }]
  });
}

/* ================================================================ OWNER DOC */
const o = [];
o.push(new Paragraph({ spacing: { before: 2000 }, children: [new TextRun({ text: "THE LUXORA COLLECTIVE", font: FONT, size: 22, bold: true, color: GOLD, characterSpacing: 60 })] }));
o.push(new Paragraph({ spacing: { before: 200 }, children: [new TextRun({ text: "The $5,000 Day", font: FONT, size: 60, bold: true, color: NAVY })] }));
o.push(new Paragraph({
  spacing: { before: 120, after: 400 },
  border: { bottom: { style: BorderStyle.SINGLE, size: 12, color: GOLD, space: 10 } },
  children: [new TextRun({ text: "Commission, Incentive, and Team Goal Design", font: FONT, size: 26, color: GREY })]
}));
o.push(P("Owner and operator copy. Contains cost modeling and legal considerations. Do not distribute to staff.", { size: 22, italics: true, color: RED, after: 600 }));
o.push(P("Prepared for:  ____________________________________", { size: 22, after: 160 }));
o.push(P("Prepared by:  The Luxora Collective", { size: 22, after: 160 }));
o.push(P("Date:  ____________________________________", { size: 22, after: 900 }));
o.push(P("theluxoracollective.co", { size: 20, bold: true, color: GOLD }));
o.push(new Paragraph({ children: [new PageBreak()] }));

o.push(H1("Your Two Questions, Answered"));
o.push(H2("Question one: should I share a daily revenue goal with the team?"));
o.push(P("Yes, but only as a pace marker, and never as the thing anyone is judged on."));
o.push(P("Here is the reason, and it is mathematical rather than philosophical. A $5,000 day is roughly eight to fifteen transactions. One filler package can be $2,500. That means a single client walking in or not walking in swings the day by half the goal. On any given day, hitting $5,000 is substantially luck. Judge a team on a coin flip and they learn within a month that the scoreboard is noise, and they stop looking at it."));
o.push(P("Over a week, that variance largely washes out. Forty to seventy-five transactions is enough that the number starts reflecting skill rather than draw. This is precisely why the goal is posted daily and the money is paid weekly."));
o.push(P("Think of it the way a runner thinks about mile splits. You look at the split to know whether you are on pace. You do not win or lose the race at mile two. The daily number tells the team whether they are on pace. The week decides the outcome.", { italics: true }));
o.push(P("So: post $5,000 daily as cumulative pace, not as a pass or fail. Give the team a daily number they actually control, which is inquiries booked, consults seated, and rebooks. Pay on the week."));

o.push(H2("Question two: should I give an incentive if the week goal is met?"));
o.push(P("Yes. The weekly team bonus is the right instrument, and it happens to be the legally safest one available to a med spa. Three design points make the difference between a plan that works and a plan that quietly costs money:"));
o.push(num("Tiered, never all-or-nothing. If it is $25,000 or nothing and Wednesday goes badly, the week is dead by Thursday morning and the incentive stops working for forty percent of its life. Tiers keep something to play for every single day."));
o.push(num("Gated. A weekly revenue bonus without a discount gate is a discounting machine. The team will discover by week three that the fastest route to $25,000 is fifteen percent off, and you will have bought your own revenue at full price."));
o.push(num("Funded from margin, not from revenue. Every tier has to stay accretive. The model checks this for you."));

o.push(new Paragraph({ children: [new PageBreak()] }));
o.push(H1("The Thing That Changes This Whole Conversation"));
o.push(P("In most states, paying a percentage of medical service revenue to a non-physician is fee-splitting, and it is illegal. This is not a technicality and the exposure is not limited to a fine. State licensing boards have the power to revoke, suspend, or refuse to renew a license over it, and the person receiving the commission is exposed alongside the person paying it.", { box: RED, shade: "FBEFEF", after: 200 }));
o.push(P("The American Med Spa Association points to three areas that determine whether a state prohibits commission-based compensation: fee-splitting statutes, anti-kickback laws, and medical board opinions. Even in states with no explicit rule, a board can reach the same outcome through unprofessional conduct provisions. And the practice of paying injector commissions is widespread in this industry precisely because most owners have never been told any of this. They were trying to reward good people."));
o.push(H2("What this means for her plan"));
o.push(P("Her instinct was already the right one. When she asked about a team bonus on a weekly goal rather than a commission grid, she landed on the exact structure that healthcare attorneys and AmSpa recommend as the compliant alternative: bonuses structured around individual performance and the overall performance of the practice, plus commission on retail products and non-medical services, which is legal."));
o.push(P("That is worth saying to her directly. It positions you as the partner who protected her license rather than the consultant who handed her a commission template that could have cost it.", { italics: true }));

o.push(H2("What is safe, and what is not"));
o.push(table(
  ["Structure", "Status", "Notes"],
  [
    ["Team bonus on overall practice performance", "Safe", "Not a share of any medical fee. This is the recommended alternative in states with fee-splitting statutes, and it is the backbone of this plan."],
    ["Commission on retail product sales", "Safe", "Legal in every state. Industry range runs 5% to 15%."],
    ["Commission on non-medical services", "Usually safe", "Facials, peels performed by an esthetician. Verify in her state before switching it on."],
    ["Pre-set bonus not tied to treatment volume", "Safe", "The bonus must not be related to the number or value of treatments performed. Design it on retention, rebooking, chart quality, and reviews."],
    ["Percentage of injectable or laser revenue", "High risk", "This is the classic fee-splitting violation. Leave it at zero in the model."],
    ["Per-unit or per-procedure payment to injectors", "High risk", "Tying compensation directly to medical procedures violates fee-splitting statutes in many states."],
    ["Paying for upsell referrals to another provider", "High risk", "Can be treated as a kickback."]
  ],
  [3000, 1500, 4860]
));
o.push(P("None of the above is legal advice, and I am not a lawyer. It is the shape of the risk, drawn accurately enough that she knows which questions to ask. Before the first dollar is paid, a healthcare attorney licensed in her state needs to review the plan. AmSpa members get a complimentary introductory compliance assessment with a ByrdAdatto attorney, which is the cheapest possible way to close this out.", { italics: true, after: 200 }));

o.push(new Paragraph({ children: [new PageBreak()] }));
o.push(H1("The Architecture"));
o.push(P("Four layers. Each does a different job, and the separation is what keeps the plan both motivating and compliant."));
o.push(table(
  ["Layer", "What it is", "Who it is for", "Why it exists"],
  [
    ["1. Base", "Hourly or salary. Unchanged by this plan.", "Everyone", "Stability. Nobody performs well while worrying about rent."],
    ["2. Team weekly bonus", "Tiered pool on the $25,000 week, gated.", "Everyone", "The engine. Tied to overall practice performance, which is what makes it compliant and what makes it collaborative."],
    ["3. Retail commission", "10% of personal retail sales.", "Providers and front desk", "Legal everywhere, high margin, and the most under-worked revenue in her building."],
    ["4. Quarterly scorecard bonus", "Pre-set dollar amount on a balanced scorecard.", "Providers", "Rewards the injector without touching medical revenue. Built on retention, rebooking, chart quality, and reviews."]
  ],
  [1500, 2700, 1800, 3360]
));

o.push(H2("The tiers"));
o.push(P("Goal is $5,000 per day, five days, so $25,000 per week and $1,250,000 per year at fifty operating weeks."));
o.push(table(
  ["Tier", "Weekly revenue", "Team pool", "Percent of revenue", "What it is for"],
  [
    ["Floor (90%)", "$22,500", "$250", "1.1%", "Keeps the week alive. Cheap insurance against a dead Thursday."],
    ["Goal (100%)", "$25,000", "$500", "2.0%", "The number."],
    ["Strong (110%)", "$27,500", "$900", "3.3%", "The accelerator. The marginal dollar starts paying more."],
    ["Exceptional (120%)", "$30,000", "$1,500", "5.0%", "Still accretive. She keeps roughly $900 of the incremental margin."]
  ],
  [1600, 1600, 1300, 1500, 3360],
  { center: true }
));
o.push(P("One design tradeoff worth naming out loud, because she may raise it: paying $250 at ninety percent means paying something for missing the goal. The argument for it is that a week which is mathematically dead by Wednesday produces two days of coasting, and two coasted days cost far more than $250. The argument against it is that it softens the goal. I would keep it for the first quarter and revisit. Either way, she should make that call knowingly rather than inherit it.", { italics: true }));

o.push(H2("The gates"));
o.push(P("All four must pass or the pool pays zero, regardless of revenue. This is the part of the plan that most owners delete, and deleting it is what turns a bonus into a liability."));
o.push(table(
  ["Gate", "Threshold", "The behavior it prevents"],
  [
    ["Discounts and comps", "5% of revenue or less", "The team hitting $25,000 by discounting. Without this gate, she pays a bonus for revenue that cost her margin to buy. This is the single most important line in the plan."],
    ["Rebook at checkout", "70% or higher", "Selling today by burning tomorrow. Guests rebooked twice or more cancel at 4%. Rebooked once, 37%."],
    ["All inquiries logged", "Required", "A plan built on invented inputs pays for fiction. Data integrity is a condition of payment, not an aspiration."],
    ["Charting current", "Required", "Never let a bonus outrun the clinical record."]
  ],
  [1900, 1800, 5660]
));

o.push(H2("How the pool splits"));
o.push(P("Role weight multiplied by hours actually worked. Part-time staff are handled automatically, which removes the single most common source of resentment in team bonus plans."));
o.push(table(
  ["Role", "Shares", "Why"],
  [
    ["Front desk / coordinator", "1.25", "Weighted highest, deliberately. They have the fewest other ways to earn, and inquiry-to-booking is the highest-leverage number they fully control."],
    ["Provider", "1.00", "Already earning base plus retail commission plus the quarterly scorecard bonus. This is a second layer for them, not their primary one."],
    ["Manager", "1.50", "Accountable for the gates, not just the revenue."]
  ],
  [2400, 1200, 5760],
  { center: false }
